package com.varnalabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.webkit.*;import android.provider.OpenableColumns;import android.view.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public final class MainActivity extends Activity {
 static final String ORIGIN="https://appassets.androidplatform.net";WebView web;final ExecutorService io=Executors.newSingleThreadExecutor();String pendingPick;volatile VideoEncoder encoder;String lastExport;volatile boolean exporting;final Object encodeLock=new Object();
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMediaPlaybackRequiresUserGesture(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setOverScrollMode(View.OVER_SCROLL_NEVER);web.addJavascriptInterface(new Bridge(),"MobileNative");web.setWebViewClient(new WebViewClient(){
  @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !r.getUrl().toString().startsWith(ORIGIN+"/");}
  @Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest request){try{return resource(request);}catch(Exception e){return response("text/plain",404,"Not Found",new ByteArrayInputStream(new byte[0]),new HashMap<>());}}
 });web.setWebChromeClient(new WebChromeClient());web.loadUrl(ORIGIN+"/index.html");}
 WebResourceResponse response(String mime,int status,String reason,InputStream in,Map<String,String> headers){headers.put("X-Content-Type-Options","nosniff");headers.put("Access-Control-Allow-Origin",ORIGIN);return new WebResourceResponse(mime,"UTF-8",status,reason,headers,in);}
 WebResourceResponse resource(WebResourceRequest req)throws Exception{Uri uri=req.getUrl();if(!"https".equals(uri.getScheme())||!"appassets.androidplatform.net".equals(uri.getHost()))throw new IOException();String p=uri.getPath();if(p==null||p.contains("..")||p.contains("\\"))throw new IOException();Map<String,String> headers=new HashMap<>();if(p.startsWith("/media/")){String id=p.substring(7);File f=mediaFile(id);String mime=getPreferences(0).getString("mime:"+id,"application/octet-stream");long length=f.length(),start=0,end=length-1;String range=req.getRequestHeaders().get("Range");if(range==null)range=req.getRequestHeaders().get("range");boolean partial=false;if(range!=null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("bytes=(\\d+)-(\\d*)").matcher(range);if(!m.matches())throw new IOException("Unsupported range");start=Long.parseLong(m.group(1));end=m.group(2).isEmpty()?end:Math.min(end,Long.parseLong(m.group(2)));partial=true;}if(start<0||end<start||start>=length)return response(mime,416,"Range Not Satisfiable",new ByteArrayInputStream(new byte[0]),headers);FileInputStream in=new FileInputStream(f);in.getChannel().position(start);final long amount=end-start+1;headers.put("Accept-Ranges","bytes");headers.put("Content-Length",Long.toString(amount));if(partial)headers.put("Content-Range","bytes "+start+"-"+end+"/"+length);return response(mime,partial?206:200,partial?"Partial Content":"OK",new FilterInputStream(in){long left=amount;public int read(byte[] b,int off,int len)throws IOException{if(left<=0)return -1;int n=super.read(b,off,(int)Math.min(left,len));if(n>0)left-=n;return n;}public int read()throws IOException{if(left--<=0)return -1;return super.read();}},headers);}
 String name=p.substring(1);if(name.isEmpty())name="index.html";String mime=name.endsWith(".js")?"text/javascript":name.endsWith(".css")?"text/css":name.endsWith(".html")?"text/html":name.endsWith(".json")?"application/json":name.endsWith(".woff2")?"font/woff2":name.endsWith(".svg")?"image/svg+xml":"text/plain";return response(mime,200,"OK",getAssets().open(name),headers);}
 File mediaFile(String id)throws IOException{if(!id.matches("[a-f0-9-]{36}"))throw new IOException("Invalid media ID");File f=new File(getFilesDir(),"media/"+id);if(!f.isFile())throw new IOException("Media missing: "+id);return f;}
 void callback(String id,Object value,String error){runOnUiThread(()->{if(isDestroyed())return;web.evaluateJavascript("window.MobileReply&&MobileReply("+JSONObject.quote(id)+","+(value==null?"null":value.toString())+","+(error==null?"null":JSONObject.quote(error))+")",null);});}
 String result(Object value){return "{\"ok\":true,\"value\":"+(value==null?"null":value.toString())+"}";}String failure(Exception e){return "{\"ok\":false,\"error\":"+JSONObject.quote(e.getMessage()==null?e.toString():e.getMessage())+"}";}
 final class Bridge {
  @JavascriptInterface public String capabilities(){return "{\"platform\":\"android\",\"version\":56,\"nativeMp4\":true,\"maxPixels\":2073600,\"maxDuration\":180}";}
  @JavascriptInterface public void pick(String request,String type){runOnUiThread(()->{if(pendingPick!=null){callback(request,null,"Another picker is open");return;}pendingPick=request;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");if("media".equals(type))intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","audio/*","image/*"});try{startActivityForResult(intent,56);}catch(Exception e){pendingPick=null;callback(request,null,e.getMessage());}});}
  @JavascriptInterface public String readText(String id){try{File f=mediaFile(id);if(f.length()>20*1024*1024)throw new IOException("Text file too large");return result(JSONObject.quote(new String(java.nio.file.Files.readAllBytes(f.toPath()),"UTF-8")));}catch(Exception e){return failure(e);}}
  @JavascriptInterface public String saveText(String name,String content){try{if(content.length()>20*1024*1024)throw new IOException("Project too large");File f=exportFile(name);try(FileOutputStream o=new FileOutputStream(f)){o.write(content.getBytes("UTF-8"));}lastExport=f.getName();return result(JSONObject.quote(lastExport));}catch(Exception e){return failure(e);}}
  @JavascriptInterface public String saveImage(String base64){try{File f=exportFile("Frame_"+System.currentTimeMillis()+".png");try(FileOutputStream out=new FileOutputStream(f)){out.write(android.util.Base64.decode(base64,0));}lastExport=f.getName();return result(JSONObject.quote(lastExport));}catch(Exception e){return failure(e);}}
  @JavascriptInterface public String beginExport(int width,int height,int fps,int frames,String audio){synchronized(encodeLock){try{if(exporting)throw new IOException("Export already active");if(width<160||height<90||width%2!=0||height%2!=0||(long)width*height>2073600||fps<12||fps>30||frames<1||frames>fps*180)throw new IOException("Export supports up to 1080p, 30 fps and 180 seconds");File out=exportFile("Video_"+System.currentTimeMillis()+".mp4");encoder=new VideoEncoder(MainActivity.this,out,width,height,fps,frames,new JSONArray(audio));exporting=true;runOnUiThread(()->getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));return result(true);}catch(Exception e){if(encoder!=null)encoder.abort();encoder=null;exporting=false;return failure(e);}}}
  @JavascriptInterface public String frame(String data,int index){synchronized(encodeLock){try{if(!exporting||encoder==null)throw new IOException("Export cancelled");encoder.frame(android.util.Base64.decode(data,0),index);return result(true);}catch(Exception e){abortExport();return failure(e);}}}
  @JavascriptInterface public void finishExport(String request){io.execute(()->{synchronized(encodeLock){try{if(!exporting||encoder==null)throw new IOException("Export cancelled");String file=encoder.finish();lastExport=file;encoder=null;exporting=false;runOnUiThread(()->getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));callback(request,JSONObject.quote(file),null);}catch(Exception e){abortExport();callback(request,null,e.getMessage());}}});}
  @JavascriptInterface public void cancelExport(){VideoEncoder current=encoder;if(current!=null)current.cancelled=true;io.execute(()->{synchronized(encodeLock){if(encoder==current)abortExport();}});}
  @JavascriptInterface public void share(String name){runOnUiThread(()->{try{File f=exportFile(name);if(!f.isFile())throw new IOException("Output missing");Uri uri=Uri.parse("content://com.varnalabs.mobile.exports/"+f.getName());Intent intent=new Intent(Intent.ACTION_SEND);intent.setType(f.getName().endsWith(".mp4")?"video/mp4":f.getName().endsWith(".png")?"image/png":"application/octet-stream");intent.putExtra(Intent.EXTRA_STREAM,uri);intent.setClipData(ClipData.newRawUri("Export",uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,"Save / share"));}catch(Exception e){new AlertDialog.Builder(MainActivity.this).setMessage(e.getMessage()).setPositiveButton("OK",null).show();}});}
 }
 File exportFile(String name)throws IOException{if(name==null||!name.matches("[A-Za-z0-9_.-]{1,120}"))throw new IOException("Invalid file name");File dir=new File(getFilesDir(),"exports");dir.mkdirs();return new File(dir,name);}
 void abortExport(){synchronized(encodeLock){if(encoder!=null)encoder.abort();encoder=null;exporting=false;}runOnUiThread(()->getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=56)return;String id=pendingPick;pendingPick=null;if(id==null)return;if(result!=RESULT_OK||data==null){callback(id,null,null);return;}Uri uri=data.getData();io.execute(()->{File dest=null;try{String name="Media",mime=getContentResolver().getType(uri);try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=c.getString(0);if(!c.isNull(1)&&c.getLong(1)>2L*1024*1024*1024)throw new IOException("Media exceeds 2 GB");}}String key=UUID.randomUUID().toString();File dir=new File(getFilesDir(),"media");dir.mkdirs();dest=new File(dir,key);long count=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException("Unable to read file");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){count+=n;if(count>2L*1024*1024*1024)throw new IOException("Media exceeds 2 GB");out.write(buffer,0,n);}}if(mime==null)mime="application/octet-stream";getPreferences(0).edit().putString("mime:"+key,mime).apply();JSONObject info=new JSONObject();info.put("id",key);info.put("name",name);info.put("type",mime);info.put("url",ORIGIN+"/media/"+key);info.put("bytes",count);callback(id,info,null);}catch(Exception e){if(dest!=null)dest.delete();callback(id,null,e.getMessage());}});}
 @Override protected void onPause(){super.onPause();web.evaluateJavascript("window.MobileApp&&MobileApp.background()",null);}
 @Override public void onBackPressed(){web.evaluateJavascript("window.MobileApp&&MobileApp.back()",null);}
 @Override protected void onDestroy(){VideoEncoder current=encoder;if(current!=null)current.cancelled=true;io.execute(()->abortExport());io.shutdown();web.removeJavascriptInterface("MobileNative");web.destroy();super.onDestroy();}
}
